namespace DropLink.Services;

public sealed record LanguageOption(string Code, string Name);

public static class LocalizationService
{
    public static readonly IReadOnlyList<LanguageOption> Languages = new[]
    {
        new LanguageOption("it", "Italiano"),
        new LanguageOption("en", "English"),
        new LanguageOption("es", "Español"),
        new LanguageOption("fr", "Français"),
        new LanguageOption("de", "Deutsch"),
        new LanguageOption("pt", "Português"),
        new LanguageOption("zh", "中文"),
        new LanguageOption("ja", "日本語")
    };

    private static string _language = "en";
    public static string Language
    {
        get => _language;
        set => _language = value is not null && Translations.ContainsKey(value) ? value : "en";
    }

    public static string Get(string key) =>
        Translations[Language].TryGetValue(key, out var value) ? value :
        Translations["en"].TryGetValue(key, out value) ? value : key;

